function isGoodArray(nums) {
  let common = nums[0];

  for (let i = 1; i < nums.length; i++) {
    let a = common;
    let b = nums[i];
    while (b !== 0) {
      const remainder = a % b;
      a = b;
      b = remainder;
    }
    common = a;
    if (common === 1) {
      return true;
    }
  }
  return common === 1;
}

