function isGoodArray(nums) {
  // The array is good unless some d > 1 divides every number; such a d divides the smallest one.
  const smallest = Math.min(...nums);
  const divisors = [];
  for (let d = 1; d * d <= smallest; d++) {
    if (smallest % d === 0) divisors.push(d, smallest / d);
  }
  for (const d of divisors) {
    if (d > 1 && nums.every(v => v % d === 0)) return false;
  }
  return true;
}

