function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(1, 6);
  const limit = large ? 1e9 : 40;
  const mode = int(0, 2);
  const factor = large ? int(2, 50000) : int(2, 6);
  const nums = [];
  for (let k = 0; k < n; k++) {
    if (mode === 2) nums.push(int(1, limit));
    else nums.push(factor * int(1, Math.floor(limit / factor)));
  }
  if (mode === 1) nums[int(0, n - 1)] = int(1, limit);
  return [nums];
}
